"""Build the public formal-experiment pages from the reviewed model/config registry."""
from pathlib import Path
import argparse
import json

CSS = r'''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#182231;font:15px/1.55 system-ui,-apple-system,sans-serif}a{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}header{background:#fff;border-bottom:1px solid #dfe5ee;position:sticky;top:0;z-index:5}nav,main{max-width:1320px;margin:auto;padding:18px 26px}nav{display:flex;justify-content:space-between;align-items:center;gap:20px}nav strong{font-size:20px}nav span{display:flex;gap:22px;font-size:13px}main{padding-top:32px;padding-bottom:70px}h1{font-size:36px;line-height:1.18;letter-spacing:-1px;margin:7px 0 12px}h2{font-size:22px;margin:30px 0 14px}.eyebrow{color:#55708f;font-size:11px;font-weight:700;letter-spacing:1.5px}.muted{color:#64748b}.small{font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:24px 0}.card,.panel{background:#fff;border:1px solid #dfe5ee;border-radius:13px;padding:20px}.card h3{margin:12px 0 7px;font-size:18px}.num{font-size:27px;font-weight:750}.badge{display:inline-block;padding:3px 9px;border-radius:20px;font-size:11px;font-weight:650;background:#eaf0f7;color:#526479}.active{background:#e4f2ed;color:#19724e}.queued{background:#fff1d6;color:#97651a}.failed,.stale{background:#fde9e7;color:#a13230}.complete{background:#e5edfF;color:#255bb1}.table{overflow:auto;background:#fff;border:1px solid #dfe5ee;border-radius:13px}table{width:100%;border-collapse:collapse;min-width:820px}th,td{text-align:left;padding:15px;border-bottom:1px solid #e9edf3;vertical-align:top}th{background:#f9fbfd;font-size:12px;color:#65758d}tr:last-child td{border-bottom:0}.progress{height:5px;border-radius:8px;background:#e8edf4;margin:8px 0;overflow:hidden;min-width:90px}.progress i{display:block;height:100%;background:#3978dd}.stats{display:flex;gap:24px;flex-wrap:wrap;margin:18px 0}.stats b{display:block;font-size:23px}.casegrid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.case{border:1px solid #dfe5ee;border-radius:10px;background:white;overflow:hidden;cursor:pointer;text-align:left;padding:0;color:inherit}.case img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#edf1f6;display:block}.case .info{padding:11px;font-size:12px}.case.selected{outline:2px solid #3978dd}.case .empty{height:80px;background:#f0f3f7;padding:18px}.detail{margin:20px 0}.versions{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.versions video,.inputimage{width:100%;max-height:420px;background:#edf1f6;border-radius:8px;object-fit:contain}pre{white-space:pre-wrap;word-break:break-word;font:12px/1.6 ui-monospace,monospace;background:#f5f7fb;padding:16px;border-radius:8px;max-height:420px;overflow:auto}details{margin:10px 0;border:1px solid #e1e6ed;padding:12px;border-radius:8px}summary{cursor:pointer;font-weight:600}.notice{border-left:3px solid #e5b14b;background:#fff7e6;padding:12px 16px;margin:18px 0}.toolbar{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:22px 0}select{padding:8px;border:1px solid #dfe5ee;background:white;border-radius:6px}footer{margin-top:32px;font-size:12px;color:#8290a3}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.casegrid{grid-template-columns:repeat(4,1fr)}}@media(max-width:650px){nav,main{padding:16px}.cards,.versions{grid-template-columns:1fr}.casegrid{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}nav span{gap:12px}.toolbar{display:block}}'''

JS = r'''(()=>{const BASE=document.body.dataset.liveBase||new URL('.',location.href).href;let plan,cat,selected=null,lastDetailKey='';const $=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=x=>typeof x==='number'?Math.round(x).toLocaleString():'—',tok=x=>typeof x==='number'?(x/1000).toFixed(1)+'k':'—',mins=x=>typeof x==='number'?(x/60).toFixed(1)+' min':'—',ago=x=>{if(!x)return'尚无有效交付';const s=Math.max(0,Math.floor((Date.now()-new Date(x).getTime())/1000));if(s<60)return s+' 秒前';if(s<3600)return Math.floor(s/60)+' 分钟前';if(s<86400)return Math.floor(s/3600)+' 小时前';return Math.floor(s/86400)+' 天前'},asset=x=>x?BASE+x:'';
async function load(path,local=false){const urls=local?[new URL(path,location.href).href]:[new URL(path,BASE).href,new URL(path,location.href).href];let error;for(const url of [...new Set(urls)]){try{const r=await fetch(url+'?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}catch(e){error=e}}throw error}
function groups(b){return(cat.groups||[]).filter(g=>g.suite===b.suite&&g.track==='vision-agent')}
function state(g){if(!g)return['queued','待调度'];if(g.paused)return['queued','已暂停'];let c=g.counts||{};if(c.running)return['active',g.upstream_wait?.waiting_cases?'等待模型 / 运行中':'运行中'];if(c.pending)return['queued','队列中'];if(c.complete===g.cases_total)return['complete','已完成'];if(c.exhausted)return['failed','有终止样本'];return['queued','待调度']}
function badge(g){const[s,t]=state(g);return'<span class="badge '+s+'">'+t+'</span>'}
function cell(g,b,m){if(m.pending)return'<span class="badge queued">待确认模型</span>';const c=g?.counts||{},v=c.complete||0;return'<a href="'+b.page+'?model='+encodeURIComponent(m.key)+'"><b>'+v+' / '+b.cases+'</b></a><div class="progress"><i style="width:'+(100*v/b.cases)+'%"></i></div>'+badge(g)+'<div class="small muted" style="margin-top:6px">'+(c.running||0)+' 运行 · '+(c.pending||0)+' 待生成 · '+(c.exhausted||0)+' 终止'+(g?.reused_cases?' · '+g.reused_cases+' 历史复用':'')+'</div><div class="small muted">最近交付：'+ago(g?.latest_completion?.[0])+'</div>'}
function home(){const configured=plan.models.filter(m=>!m.pending),all=cat.groups||[];const done=all.reduce((s,g)=>s+(g.counts?.complete||0),0),running=all.reduce((s,g)=>s+(g.counts?.running||0),0);$('headline').innerHTML='<p class="eyebrow">CODING AGENTS AS PIXEL WORLD MODELS</p><h1>PixelWorld · 主实验</h1><p class="muted">4 个 benchmark · Vision · 720p / 24 FPS · '+configured.length+' / '+plan.expected_models+' 个模型已配置</p><div class="stats"><div><b>'+done+'</b>有效交付</div><div><b>'+running+'</b>当前运行</div><div><b>'+num(configured.length*537)+'</b>已注册 case</div></div>';$('content').innerHTML='<div class="cards">'+plan.benchmarks.map(b=>{const gs=groups(b),v=gs.reduce((s,g)=>s+(g.counts?.complete||0),0),r=gs.reduce((s,g)=>s+(g.counts?.running||0),0);return'<article class="card"><span class="badge '+(r?'active':'queued')+'">'+(r?'运行中':'队列中')+'</span><h3>'+esc(b.name)+'</h3><p class="muted small">'+esc(b.spec)+'</p><div class="num">'+v+' <span class="muted small">/ '+(b.cases*configured.length)+'</span></div><p class="small muted">'+b.cases+' prompts / model</p><a href="'+b.page+'">查看模型与视频 →</a></article>'}).join('')+'</div><h2>模型 × Benchmark</h2><div class="table"><table><thead><tr><th>模型 · Vision</th>'+plan.benchmarks.map(b=>'<th>'+esc(b.short)+'</th>').join('')+'</tr></thead><tbody>'+plan.models.map(m=>'<tr><td><b>'+esc(m.label)+'</b></td>'+plan.benchmarks.map(b=>'<td>'+cell(groups(b).find(g=>g.model_key===m.key),b,m)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="small muted">第六个模型确认后补入同一矩阵。生成完成后进入独立评测；未完成评测的分数不显示为零。</p><p><a href="analyses.html">分析实验计划 →</a> · <a href="https://siyuanmacs.github.io/physics-iq-pixel-preview/">历史实验 / Legacy →</a></p>'}
async function detail(path){const d=await load(path);const playing=$('detail')?.querySelector('video');if(playing&&!playing.paused)return;const diag=d.diagnostics||{};let text='<section class="panel detail"><div class="toolbar"><h2 style="margin:0">'+esc(d.case_id)+' · Attempt '+d.attempt+'</h2><span class="badge '+(d.delivery_status==='complete'?'complete':d.delivery_status==='running'?'active':'failed')+'">'+esc(d.delivery_status)+'</span></div>'+(d.reused?'<p class="small muted">历史复用 · '+esc(d.provenance?.source_suite)+' · 原始运行环境 '+esc(d.provenance?.original_filesystem_policy)+'</p>':'')+'<div class="stats"><div><b>'+tok(d.input_tokens)+'</b>Input tokens</div><div><b>'+tok(d.output_tokens)+'</b>Output tokens</div><div><b>'+mins(d.duration_seconds)+'</b>本次耗时</div><div><b>'+d.candidates.length+'</b>保存候选</div></div><details open><summary>任务指令</summary><p>'+esc(d.prompt)+'</p></details>';if(d.source_video)text+='<details><summary>输入源视频</summary><video controls preload="none" src="'+asset(d.source_video)+'"></video></details>';else if(d.first_frame)text+='<details><summary>输入首帧</summary><img class="inputimage" src="'+asset(d.first_frame)+'"></details>';if(!d.candidates.length)text+='<div class="notice">尚未保存可播放候选。下面展示当前工具记录与交付诊断。</div>';text+='<div class="versions">'+d.candidates.map(c=>'<article><p><b>'+esc(c.label)+'</b> <span class="small muted">'+esc(c.utc||'')+'</span></p>'+(c.preview_mp4?'<video controls preload="none" poster="'+asset(c.poster)+'" src="'+asset(c.preview_mp4)+'"></video>':'<img class="inputimage" src="'+asset(c.poster)+'">')+(c.code?'<details><summary>生成代码</summary><pre>'+esc(c.code)+'</pre></details>':'')+'</article>').join('')+'</div><details '+(d.delivery_status==='complete'?'':'open')+'><summary>交付与失败诊断</summary><pre>'+esc(JSON.stringify({diagnostics:diag,validation:d.validation,budget_exhausted:d.budget_exhausted},null,2))+'</pre></details><details><summary>工具与执行记录 · '+d.events.length+' 条</summary>'+d.events.map(e=>'<details><summary>'+esc(e.kind)+' · '+esc(e.utc||'')+'</summary>'+(e.command?'<pre>'+esc(e.command)+'</pre>':'')+(e.aggregated_output?'<pre>'+esc(e.aggregated_output)+'</pre>':'')+(e.text?'<pre>'+esc(e.text)+'</pre>':'')+(e.images||[]).map(i=>'<img class="inputimage" src="'+asset(i)+'">').join('')+'</details>').join('')+'</details></section>';$('detail').innerHTML=text;lastDetailKey=path}
async function benchmark(){const b=plan.benchmarks.find(x=>x.id===document.body.dataset.benchmark),gs=groups(b),model=new URLSearchParams(location.search).get('model');$('headline').innerHTML='<p class="eyebrow">MAIN EXPERIMENT · VISION</p><h1>'+esc(b.name)+'</h1><p class="muted">'+esc(b.spec)+' · '+b.cases+' cases / model</p><p><a href="index.html">← 主实验总览</a></p>';if(!model){$('content').innerHTML='<div class="table"><table><thead><tr><th>模型</th><th>生成进度</th><th>Input 均值</th><th>Output 均值</th><th>耗时均值</th><th>评测</th></tr></thead><tbody>'+plan.models.map(m=>{let g=gs.find(x=>x.model_key===m.key);return'<tr><td><a href="?model='+encodeURIComponent(m.key)+'">'+esc(m.label)+'</a></td><td>'+cell(g,b,m)+'</td><td>'+tok(g?.mean_input_tokens)+'</td><td>'+tok(g?.mean_output_tokens??g?.mean_output_tokens_cached)+'</td><td>'+mins(g?.mean_duration_seconds)+'</td><td class="muted">待评测</td></tr>'}).join('')+'</tbody></table></div><p class="small muted">均值按有效交付的首次成功 attempt 统计；未报告 usage 显示为 —。</p>';return}const g=gs.find(x=>x.model_key===model),m=plan.models.find(x=>x.key===model);if(!g){$('content').innerHTML='<div class="notice">'+esc(m?.label||model)+' 尚未进入已配置队列。</div>';return}const data=await load(g.path);const histories=Object.entries(data.cases||{}).sort(([a],[b])=>a.localeCompare(b));$('content').innerHTML='<h2>'+esc(m?.label||model)+' · Vision</h2><div class="stats"><div><b>'+(g.counts?.complete||0)+' / '+b.cases+'</b>有效交付</div><div><b>'+(g.counts?.running||0)+'</b>运行中</div><div><b>'+tok(g.mean_input_tokens)+'</b>Input 均值</div><div><b>'+tok(g.mean_output_tokens??g.mean_output_tokens_cached)+'</b>Output 均值</div><div><b>'+mins(g.mean_duration_seconds)+'</b>耗时均值</div></div><p>'+badge(g)+' <span class="small muted">'+histories.length+' 个样本已有详情</span></p><div class="casegrid">'+histories.map(([cid,h])=>{const a=h.slice().sort((a,b)=>Number(b.reused)-Number(a.reused)||Number(b.status==='complete')-Number(a.status==='complete')||b.attempt-a.attempt)[0];return'<button class="case '+(selected===cid?'selected':'')+'" data-case="'+esc(cid)+'">'+(a.poster?'<img loading="lazy" src="'+asset(a.poster)+'">':'<div class="empty">'+esc(a.status)+'</div>')+'<div class="info"><b>'+esc(cid)+'</b><br>'+esc(a.status)+' · '+h.length+' 次记录<br>'+tok(a.output_tokens)+' output · '+a.candidate_count+' 候选</div></button>'}).join('')+'</div>';for(const el of document.querySelectorAll('[data-case]'))el.onclick=()=>{selected=el.dataset.case;showSelected()};
async function showSelected(){let h=(data.cases||{})[selected];if(!h)return;h=h.slice().sort((a,b)=>Number(b.reused)-Number(a.reused)||Number(b.status==='complete')-Number(a.status==='complete')||b.attempt-a.attempt);$('attempts').innerHTML='<label class="small muted">运行记录 </label><select id="attempt-select">'+h.map(a=>'<option value="'+esc(a.detail)+'">Attempt '+a.attempt+' · '+esc(a.status)+'</option>').join('')+'</select>';$('attempt-select').onchange=()=>detail($('attempt-select').value);await detail(h[0].detail)}if(selected)await showSelected()}
async function poll(){try{if(!plan)plan=await load('experiment_plan.json',true);cat=await load('catalogue.json');$('sync').textContent='数据更新：'+ago(cat.updated_utc)+' · '+new Date(cat.updated_utc).toLocaleTimeString();if(document.body.dataset.benchmark)await benchmark();else home()}catch(e){$('sync').textContent='同步等待 · '+e.message}}poll();setInterval(poll,15000)})();'''

BENCHMARKS = [
    ('physics_iq','Physics-IQ Verified','Physics-IQ',198,'physics_iq_720p24fps','physics_iq_baseline.html','1280×720 · 24 FPS · 5 秒 · I2V'),
    ('robojudge','RoboJudge shared-50','RoboJudge',50,'robojudge_main720p24fps','robojudge.html','保留比例，短边 720 · 24 FPS · 5 秒 · I2V'),
    ('pcve','PCVE-RigidBench','PCVE',129,'pcve_standard720p24fps','pcve_rigid.html','1280×720 · 24 FPS · 4 秒 · Video Editing'),
    ('phygenbench','PhyGenBench','PhyGenBench',160,'phygenbench_t2v_main720p24fps','phygen_pixelspace.html','1280×720 · 24 FPS · 5 秒 · T2V'),
]


def build(bundle: Path, checkout: Path):
    meta=json.loads((bundle/'bundle.json').read_text());models={}
    for paths in meta['configs'].values():
        config=json.loads((bundle/paths['full']).read_text())
        for model in config['models']:
            models[model['key']]={'key':model['key'],'label':model.get('display_name',model['model'].split('/')[-1])}
    ready=json.loads((bundle/'READINESS.json').read_text())
    expected=ready.get('model_slots_expected',len(models))
    if len(models)<expected:models['awaiting-model']={'key':'awaiting-model','label':'第六个模型 · 待确认','pending':True}
    plan={'expected_models':expected,'models':list(models.values()),'benchmarks':[dict(zip(('id','name','short','cases','suite','page','spec'),b))for b in BENCHMARKS]}
    root=checkout/'pixelworld';root.mkdir(exist_ok=True)
    (root/'experiment_plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2))
    (root/'formal.css').write_text(CSS)
    (root/'formal.js').write_text(JS)
    shell='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PixelWorld · Live Experiments</title><link rel="stylesheet" href="formal.css?v=20261117"></head><body DATA><header><nav><strong><a href="index.html">PixelWorld</a></strong><span><a href="index.html">主实验</a><a href="analyses.html">分析</a><a href="https://huggingface.co/datasets/HuggingFriends/PixelWorld">视频与记录</a><a href="https://huggingface.co/datasets/HuggingFriends/PixelWorld/tree/main/traces">完整 Trace</a><a href="https://github.com/SiyuanMaCS/PixelWorld">GitHub</a><a href="https://siyuanmacs.github.io/physics-iq-pixel-preview/">Legacy</a></span></nav></header><main><div id="headline"></div><p class="small muted" id="sync">正在加载实时数据…</p><div id="content"></div><div id="attempts"></div><div id="detail"></div><footer>新运行：Vision · Codex 0.169.0 · case-only-v1 · 1M output tokens / attempt（新 attempt）· 最多 5 次真实 attempt。已完成的 100k 交付保留原始记录。</footer></main><script src="formal.js?v=20261117-delivery-age"></script></body></html>'''
    paths=['index.html','pixelworld-index.html']
    for name in paths:(root/name).write_text(shell.replace('DATA',''))
    for b in BENCHMARKS:
        (root/b[5]).write_text(shell.replace('DATA','data-benchmark="'+b[0]+'"'))
    for name in ['physics_iq_resolution.html','physics_iq_512w24fps.html']:
        (root/name).write_text(shell.replace('DATA','data-benchmark="physics_iq"'))
    (root/'phygenbench.html').write_text(shell.replace('DATA','data-benchmark="phygenbench"'))
    analysis='''<p class="eyebrow">ANALYSIS · TWO MODELS</p><h1>分析实验</h1><p class="muted">GPT-6.1-Sol · DeepSeek-V4.1-Flash</p><div class="table"><table><tr><th>问题</th><th>配置</th><th>当前阶段</th></tr><tr><td>Text vs Vision</td><td>四个 benchmark，补 Text；共享 Vision 主实验</td><td>准备 / 主实验优先</td></tr><tr><td>分辨率</td><td>Physics-IQ：480p / 720p / 1080p，24 FPS</td><td>准备</td></tr><tr><td>FPS</td><td>Physics-IQ：12 / 24 / 48 FPS，720p</td><td>准备</td></tr><tr><td>Thinking</td><td>原生支持的较低 / High / 较高档位</td><td>核对模型支持</td></tr><tr><td>初始化</td><td>PhyGenBench：T2V / QwenInit-I2V × Text / Vision</td><td>准备首帧与队列</td></tr><tr><td>自主修订与成本</td><td>首个有效候选 / 最终候选；真实调用与 token</td><td>复用已记录轨迹</td></tr></table></div><p><a href="index.html">← 主实验</a></p>'''
    (root/'analyses.html').write_text(shell.replace('DATA','').replace('<div id="headline"></div>',analysis).replace('<script src="formal.js?v=20261117-delivery-age"></script>','').replace('正在加载实时数据…','分析配置尚未统一启动，不计入主实验进度。'))
    return plan


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--bundle',type=Path,required=True);p.add_argument('--checkout',type=Path,required=True)
    args=p.parse_args();plan=build(args.bundle.resolve(),args.checkout.resolve())
    print(json.dumps({'configured_models':len([m for m in plan['models']if not m.get('pending')]),'benchmarks':len(plan['benchmarks'])}))
